  "decline_reason": "",
  "claims": [
    {
      "text": "The internal review described in these passages is review of an FOI decision by the agency that made it.",
      "quotes": [
        {
          "ref": "TMM/Part61/2/2/4",
          "quote": "Two categories of FOI decision can be internally reviewed under the FOI Act by the agency who made the decision"
        }
      ],
      "authority": "manual"
    },
    {
      "text": "For an access refusal decision, the Manual says the FOI applicant may apply for internal review.",
      "quotes": [
        {
          "ref": "TMM/Part61/2/2/4",
          "quote": "an ‘access refusal decision’ (Section 53A) in respect of which the FOI applicant may apply for internal review (Section 54)"
        }
      ],
      "authority": "manual"
    },
    {
      "text": "For an access grant decision, the Manual says an affected third party may apply for internal review.",
      "quotes": [
        {
          "ref": "TMM/Part61/2/2/4",
          "quote": "an ‘access grant decision’ (Section 53B) in respect of which an affected third party may apply for internal review (Section 54A)."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "The Manual gives a general deadline of 30 calendar days after notification of an access refusal or access grant decision.",
      "quotes": [
        {
          "ref": "TMM/Part61/2/2/4/2",
          "quote": "A person generally has 30 calendar days after being notified of an agency’s access refusal or access grant decision to apply for internal review (Section 54B(1)(a))."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "For access refusal decisions involving incomplete access or purported access that was not actually given, the Manual records a potentially longer deadline: 30 calendar days after notification or 15 calendar days after access is given or purportedly given, whichever period is longer.",
      "quotes": [
        {
          "ref": "TMM/Part61/2/2/4/2",
          "quote": "A longer period may apply for the following access refusal decisions: a decision giving access to documents in accordance with a request but not giving access to all the documents covered by the request, or a decision purporting to give access to documents in accordance with a request but not in fact doing so."
        },
        {
          "ref": "TMM/Part61/2/2/4",
          "quote": "The time limit for applying for internal review is either 30 calendar days after notification of the decision or 15 calendar days after access to documents is given or purported to be given, whichever period is longer (Section 54B(1)(b))."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "The Manual says the agency can extend the period for applying for internal review, even after the statutory period has expired.",
      "quotes": [
        {
          "ref": "TMM/Part61/2/2/4",
          "quote": "Under Section 54B(2), it is possible for an agency to extend the period for an applicant to apply for internal review, even if the statutory period has already expired."
        }
      ],
      "authority": "manual"
    },
    {
      "text": "No FOI Act text was supplied, so this answer reports the Manual’s account rather than independently verifying the legislation; if you mean internal review of a trade mark decision rather than an FOI decision, the supplied passages do not establish the deadline or eligibility.",
      "quotes": [],
      "authority": "none"
    }
  ],
